from 写入第二遍 import add
add('22_004',10,'16:9，高位俯视双人全景，青伏在画面左下，董白站在右上，两人之间留完整石面；镜头沿两人连线缓慢降近，落幅仍保留青的展开双腿与董白的鞋位。','青脸侧贴地，只把嘴角很轻地动了一下，气音般回答；手指在石面上松松蜷起，双腿仍摊着。董白听到回答先稍稍松肩，紧接着把一只手放到腰侧，脚尖转向青，低头追问身份；说到被抢走功劳，她上身前倾，空着的手张开半掌，最后又把手收回身边。青一直伏着听完，头旁发尾只被风推了一小段。','灰绿不规则石铺地面占满背景，近层板缝深灰，细砂稀疏；高位光下二人的短影各留在身侧。','上方冷白云光为主，石面反出弱中性补光，尚未出现直射晨光。','青呼气擦过地面的微声，董白鞋尖转石一声轻擦，衣料随叉腰轻绷。',ja=['…まだ。もうすぐだけど。','あなた、一体何者なの？どうして毎回私の手柄を横取りするのよ。ほんと、腹が立つ。'],tone='青虚弱地开一句黑色幽默；董白先确认她能说话，随即转成不服气的抱怨，末句短促收回。',kind='mixed',phase='state',node={'叙事阶段':'青伏地回答，董白抱怨功劳被抢'},meaning='俯视青卧地与董白站立的原格距离保留，两人各自回应，青未被扶起。',characters=['青','董白'],card={'opening':'确认青还能开口后，董白又想起自己的功劳。','beats':['青气音回答，董白略松肩','董白叉腰转脚追问','前倾张掌抱怨后收手，青伏地听完'],'coupling':'董白先听到活着的回应再放松，埋怨接在关心之后。','landing':'青仍卧地，准备把功劳让给她。'})
add('23_001',5.5,'16:9，贴地看青脸的近景，脸居画面中央偏左，一眼闭、一眼半睁，笑口和侧贴地的脸颊同框；固定机位，散发铺过下缘。','青把半睁的眼睛转向董白鞋位的画外方向，嘴角先翘起一点，随即张嘴把解决办法慢慢说完；那只闭眼始终没力睁开，笑里露出短短一线齿。说完，她脸颊重新贴实石面，唇角还留着一点笑，呼吸把鼻旁细灰吹散一小块，发丝在地面轻轻滑开。','灰绿石铺地面紧贴脸旁，石纹与深灰缝清晰，远层淡米灰薄尘虚化。','冷白云光沿发顶与脸侧柔亮，脸贴石的一边由地面弱反光托起，旧擦痕保持。','微弱喘气，脸旁发丝与石面的细擦，近处空地风声。',ja=['…じゃあ、あなたが解決したって皆に言えばいいよ…'],tone='青虚弱地笑着提出让功，语气真诚又带一点顺水推舟的轻松，句尾气息软下去。',kind='mixed',phase='reaction',node={'叙事阶段':'青主动把功劳让给董白'},meaning='青侧脸贴地、单眼闭与露齿笑保留，疲惫中仍主动回应别人。',characters=['青'],card={'opening':'青现在更想有人接手，功劳并非她眼前所需。','beats':['半睁眼转向董白，嘴角先挑起','笑着把建议说完','脸贴回石面，笑意留一线'],'coupling':'让步既承接对方抱怨，也延续青活泼而善于互动的底色。','landing':'建议送出，轮到董白接收。'})
add('23_002',7,'16:9，董白向前探身的头肩近景，脸居画面中央，两根高马尾在上方张开；机位略低于她眼睛，随她前探轻退，落幅保留大张笑口与两肩。','董白眼睛骤然睁得更圆，眉尖向上跳，原来微抿的嘴一下展开成大笑；她向青凑近，第一轮确认连着问出，句末下巴向前一点，像急着把约定钉住。听完自己的话，她上身又直回少许，笑口收小但仍露着齿，目光在青脸上停住，第二句夸得格外痛快；马尾被前探带起，最后绕过肩侧慢慢落回。','蓝灰云天在马尾外侧铺开，薄米灰尘退在低处，人物后方淡灰云纹柔和。','上方冷白柔光照亮睁大的双眼，黑发与亮黑领口留软反光，脸侧明暗稳定。','突然前探的衣料短擦，马尾掀起一记轻风，鞋底重心前移小响。',ja=['え？本当に？約束よ？！','この仕事で、あんたみたいに話の分かる人は珍しいわ。'],tone='董白第一句由惊喜冲成急切确认，末尾重重约定；第二句畅快夸赞，态度明显转好。',kind='mixed',phase='reaction',node={'叙事阶段':'董白闻让功转喜，准备上前扶起青'},meaning='董白圆眼大笑、前探与好感突增的原作表情保留，图形拟字转为表情节奏而不生成字幕。',characters=['董白'],card={'opening':'能拿到功劳让董白瞬间改观。','beats':['眉眼猛开、大笑前探确认','下巴一点钉约定','身子稍回直，痛快夸青'],'coupling':'情绪转折先于身体收回，马尾拖住兴奋的余势。','landing':'她已愿意靠近并帮青起身。'})
